"""Seed loader: loads the synthetic demo data (scripts/reset_demo.sql, generated by T0 from scripts/seed/*.json).

    python -m app.db.seed [path/to/reset_demo.sql] [--url postgresql+asyncpg://...]

The SQL is TRUNCATE + INSERT in one transaction, so it can be re-run. Embeddings are filled later by the
backend at start-up (app.rag.embed.fill_missing_embeddings).
"""

from __future__ import annotations

import argparse
import asyncio
from pathlib import Path

import asyncpg

from app.config import get_settings

DEFAULT_SQL = Path(__file__).resolve().parents[3] / "scripts" / "reset_demo.sql"


def plain_dsn(url: str) -> str:
    return url.replace("postgresql+asyncpg://", "postgresql://")


async def load_seed(sql_path: Path = DEFAULT_SQL, url: str | None = None) -> dict[str, int]:
    conn = await asyncpg.connect(plain_dsn(url or get_settings().database_url))
    try:
        await conn.execute(sql_path.read_text(encoding="utf-8"))  # no args → simple protocol, multi-statement OK
        counts = {}
        for t in ("customers", "cards", "branches", "loan_products", "kb_chunks", "agents", "calls", "tickets"):
            counts[t] = await conn.fetchval(f"SELECT count(*) FROM {t}")  # noqa: S608 (fixed table names)
        return counts
    finally:
        await conn.close()


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("sql", nargs="?", default=str(DEFAULT_SQL))
    ap.add_argument("--url", default=None)
    a = ap.parse_args()
    print(asyncio.run(load_seed(Path(a.sql), a.url)))


if __name__ == "__main__":
    main()
